import re
import datetime

from ta_moler.events.rtg_ctrl.genericrtg_ctrl_lineevent import GenericRtgCtrlLineEvent


class DetectedLink(GenericRtgCtrlLineEvent):
    """Detected link event class."""

    # Example line: [ 7050.154028] platform[887]: ccs: 2019-09-06T11:45:15.048Z ::Detected link: 4, PI: 63
    re_detected_link = re.compile(r'::Detected link: (?P<LINK>\d+), PI: (?P<PI>\d+)')

    def __init__(self, connection, till_occurs_times=-1, runner=None):
        """Event for detected link.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        :param runner: Runner to run event
        """
        super(DetectedLink, self).__init__(connection=connection, runner=runner,
                                           till_occurs_times=till_occurs_times,
                                           detect_patterns=[self.re_detected_link],
                                           match='any')


EVENT_OUTPUT = """toor4nsn@fzm-lsp-k2:~# [ 7049.991663] platform[887]: ccs: RTG: Serdes Re-enabled 2
[ 7049.992178] platform[887]: ccs: RTG: Serdes Re-enabled 3
[ 7050.154028] platform[887]: ccs: 2019-09-06T11:45:15.048Z ::Detected link: 4, PI: 63"""

EVENT_KWARGS = {"till_occurs_times": 1}

EVENT_RESULT = [{'line': '[ 7050.154028] platform[887]: ccs: 2019-09-06T11:45:15.048Z ::Detected link: 4, PI: 63',
                 'groups': (4, 63),
                 'named_groups': {'LINK': 4, 'PI': 63},
                 'matched': '::Detected link: 4, PI: 63',
                 'time': datetime.datetime.now()}]
